    // solicitar la palabra a buscar al usuario
    cout << "Introduzca la palabra a buscar: ";
    getline(cin, wordToSearch);

    // abrir el archivo para lectura
    ifstream inputFile;
    inputFile.open("archivo.txt");
    if (!inputFile.is_open()) {
        cerr << "Error al abrir el archivo." << endl;
        return 1;
    }

    // leer línea por línea y contar apariciones de la palabra
    while (getline(inputFile, currentLine)) {
        size_t pos = 0;
        while ((pos = currentLine.find(wordToSearch, pos)) != string::npos) {
            count++;
            pos += wordToSearch.length();
        }
    }

    // cerrar el archivo
    inputFile.close();

    // mostrar el resultado
    cout << "La palabra '" << wordToSearch << "' aparece " << count << " veces en el archivo." << endl;

    return 0;
}
